    "explanation": "**Đáp án đúng: C**. Để viết yêu cầu rõ ràng và súc tích, cần dùng ngôn ngữ đơn giản, tránh thuật ngữ chuyên ngành khó hiểu (jargon), viết câu ngắn gọn, trực tiếp và sử dụng thuật ngữ nhất quán.",
    "imageUrl": "/images/swr-fe/su26-b5/q22.webp",
    "imageCaption": "Đề 02 — Câu 22 (Đề gốc)"
