    "chapterId": "swr-ch-mock",
    "source": "imported",
    "examTarget": "both",
    "difficulty": "understand",
    "type": "single",
    "prompt": "[Đề 10 - Câu 1] What is the role of a 'Project Champion' in Karl Wiegers' requirements engineering process?",
