    "chapterId": "swr-ch-mock",
    "source": "imported",
    "examTarget": "both",
    "difficulty": "remember",
    "type": "single",
    "prompt": "[Đề 11 - Câu 8] What does the MoSCoW prioritization technique stand for?",
