    "chapterId": "swr-ch-mock",
    "source": "imported",
    "examTarget": "both",
    "difficulty": "remember",
    "type": "single",
    "prompt": "[Đề 11 - Câu 11] Which of the following terms describes the tendency for the project scope to continually expand beyond its original boundaries?",
